text:
& .container {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  max-block-size: inherit;
  box-sizing: border-box;

  tr:not(.children) & .twisty {
    visibility: hidden;
  }

  & .twisty {
    inline-size: 16px;
    block-size: 16px;
    min-block-size: auto;
    min-inline-size: auto;
    flex-shrink: 0;
    padding: 0;
    margin: 0;
    background-color: transparent;
    border: none;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  & .twisty-icon {
    inline-size: 12px;
    block-size: 12px;
    content: var(--icon-nav-down-sm);

    @media (prefers-reduced-motion: no-preference) {
      transition: transform 200ms ease;
    }
  }

  tr.children.collapsed & .twisty-icon {
    transform: rotate(-90deg);

    &:dir(rtl) {
      transform: rotate(90deg);
    }
  }

  & .icon {
    margin-inline-start: 3px;
  }

  & div {
    margin-inline-start: 6px;
    line-height: 1.5;
  }
